const getLang=()=>localStorage.getItem('sayda-lang')==='en'?'en':'ar'; const t=()=>getLang()==='en'?en:ar;
const menuCats=[['all_house_needs','كل احتياجات المنزل','Home essentials'],['best_offers','أفضل العروض','Best offers'],['cleaning_supplies','مستلزمات تنظيف','Cleaning supplies'],['electronics','إلكترونيات وأجهزة ذكية','Electronics & smart devices'],['fitness','رياضة منزلية','Home fitness'],['furniture_outdoor','أثاث خارجي','Outdoor furniture'],['home_appliances','أجهزة منزلية','Home appliances'],['home_improvement','تحسينات منزلية','Home improvement'],['home_storage','تخزين منزلي','Home storage'],['natural_beauty','الجمال الطبيعي','Natural beauty'],['special_car','السيارة المميزة','Car essentials'],['toys_and_games','ألعاب للصغار والكبار','Toys & games']];
function savedCount(){try{return JSON.parse(localStorage.getItem('sayda-cart')||'[]').reduce((n,x)=>n+(x.qty||1),0)}catch{return 0}}
function renderHeader(){const header=document.querySelector('header');if(!header)return;const d=t(),hasSearch=location.pathname==='/'||location.pathname==='/index.html'||location.pathname.startsWith('/categories/');const search=hasSearch?`<div class="header-search"><input id="search" type="search" autocomplete="off" placeholder="${d.search}" aria-label="${d.search}"><button class="search-close" type="button" aria-label="${d.closeSearch}">×</button></div>`:'';const menuLinks=[`<a href="/">${d.home}</a>`,`<span class="menu-head">${d.categories}</span>`,...menuCats.map(c=>`<a href="/categories/${c[0]}.html">${getLang()==='en'?c[2]:c[1]}</a>`),`<a href="/legal/privacy-terms.html">${d.privacy}</a>`,`<a href="/legal/shipping-returns.html">${d.shipping}</a>`,`<a href="/legal/contact.html">${d.contact}</a>`].join('');header.innerHTML=`<div class="sitebar ${hasSearch?'has-search':'no-search'}"><button class="menu-button" type="button" aria-label="${d.menu}" aria-expanded="false">☰</button>${search}<div class="header-actions"><button class="cart-button" type="button" aria-label="${d.cart}">🛒 <b id="count">${savedCount()}</b></button><button class="lang-button" type="button" aria-label="${d.changeLang}">${getLang()==='en'?'عر':'EN'}</button><button class="theme-button" type="button" aria-label="${d.changeTheme}">${localStorage.getItem('sayda-theme')==='dark'?'☀':'☾'}</button></div><a class="brand-link" href="/" aria-label="${d.home}"><img class="logo" src="/assets/logo.png" alt="${d.brandAlt}"></a><nav class="site-menu">${menuLinks}</nav></div>`;
const bar=header.querySelector('.sitebar'),input=header.querySelector('#search');
header.querySelector('.menu-button').onclick=e=>{const active=bar.classList.toggle('menu-open');e.currentTarget.setAttribute('aria-expanded',String(active))};
header.querySelector('.lang-button').onclick=()=>setLanguage(getLang()==='en'?'ar':'en');
header.querySelector('.theme-button').onclick=()=>{localStorage.setItem('sayda-theme',localStorage.getItem('sayda-theme')==='dark'?'light':'dark');applyLanguage()};
header.querySelector('.cart-button').onclick=()=>typeof window.openCart==='function'?window.openCart():location.assign('/?cart=1');
if(input){input.addEventListener('focus',()=>bar.classList.add('search-open'));input.addEventListener('blur',()=>setTimeout(()=>bar.classList.remove('search-open'),140));input.addEventListener('keydown',e=>{if(e.key==='Escape'){input.blur();bar.classList.remove('search-open')}});header.querySelector('.header-search').addEventListener('click',()=>{bar.classList.add('search-open');input.focus()});header.querySelector('.search-close').onclick=()=>{input.value='';input.dispatchEvent(new Event('input',{bubbles:true}));input.blur();bar.classList.remove('search-open')}}
}
function homeText(){const cat=window.SAYDA_CATEGORY,row=cat?menuCats.find(c=>c[0]===cat):null,isEn=getLang()==='en';const put=(id,a,b)=>{const x=document.getElementById(id);if(x)x.textContent=isEn?b:a};if(row){document.title=(isEn?row[2]:row[1])+' | '+(isEn?'Syda':'صيدة');put('heroTitle',row[1],row[2]);put('heroSubtitle','تصفح منتجات هذا القسم بالكامل','Browse all products in this category');}if(!document.getElementById('heroTitle'))return;if(!row)put('heroTitle','كل ما تحتاجه، في مكان واحد','Everything you need, in one place');if(!row)put('heroSubtitle','منتجات مختارة بعناية للمنزل والجمال والإلكترونيات والسيارة وأكثر.','Carefully selected products for home, beauty, electronics, cars and more.');put('categoriesTitle',ar.categories,en.categories);put('categoryLabel',ar.chooseCategory,en.chooseCategory);put('productsTitle',ar.products,en.products);put('sortLabel','ترتيب النتائج','Sort results');const sort=document.getElementById('sort');if(sort){const labels=isEn?['Default order','Price: low to high','Price: high to low','Name']:['الترتيب الافتراضي','السعر: من الأقل للأعلى','السعر: من الأعلى للأقل','الاسم'];[...sort.options].forEach((o,i)=>o.textContent=labels[i])}}
function productText(){const p=window.__saydaProduct||(typeof product!=='undefined'?product:null);if(!p)return;const isEn=getLang()==='en',d=t(),name=isEn?(p.nameEn||p.name):p.name,desc=isEn?(p.descriptionEn||p.description):p.description;document.title=`${name} | ${isEn?'Syda':'صيدة'}`;const h=document.querySelector('.info h1'),dc=document.querySelector('.description'),description=dc?dc.querySelector('p'):null,dh=dc?dc.querySelector('h2'):null;if(h)h.textContent=name;const price=document.querySelector('.info .price');if(price)price.textContent=Number.isFinite(Number(p.price))?`${Number(p.price)} ${isEn?'SAR':'ر.س'}`:(isEn?'Price on request':'السعر عند الطلب');if(dc){const _e=desc.split(/\r?\n/).map(x=>x.replace(/\s+/g,' ').trim()).filter(x=>x&&!/^[ـ\-\—_=*•·. ]{3,}$/.test(x)).map(x=>`<p>${x.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</p>`).join('');dc.innerHTML=`<h2>${d.description}</h2>${_e||''}`;}const notices=document.querySelectorAll('.info .notice');if(notices[0])notices[0].textContent=d.shippingFree;if(notices[1])notices[1].textContent=d.payment;const add=document.querySelector('#a');if(add)add.textContent=d.add;const breadcrumb=document.querySelector('.wrap>p');if(breadcrumb)breadcrumb.innerHTML=`<a href="/">${d.home}</a> ← ${isEn?'Product details':'تفاصيل المنتج'}`;const crumbs=document.querySelector('.crumbs'),pill=document.querySelector('.cat-pill');if(pill){const cl=crumbs?crumbs.dataset:null,nm=isEn?(cl&&cl.caten)||'':(cl&&cl.catlabel)||'';if(nm)pill.textContent=nm;}const trusts=document.querySelectorAll('.trust-row>span');if(trusts.length){const tt=isEn?['Fast delivery','Secure payment','15-day returns']:['توصيل سريع','دفع آمن','إرجاع خلال 15 يوم'];trusts.forEach((s,i)=>s.textContent=tt[i]||s.textContent);}const tiersTitle=document.querySelector('.tiers-title');if(tiersTitle)tiersTitle.textContent=isEn?'Quantity and price (bulk discount)':'الكمية والسعر (خصم على الكميات)';document.querySelectorAll('.tier-chip em').forEach(e=>{if(!e.dataset.ar)e.dataset.ar=e.textContent;const m=/[0-9]+(?:\.[0-9]+)?%/.exec(e.dataset.ar);e.textContent=isEn?(m?'Save '+m[0]:e.dataset.ar):e.dataset.ar;});document.querySelectorAll('.tier-chip small').forEach(s=>{if(!s.dataset.ar)s.dataset.ar=s.textContent;s.textContent=isEn?s.dataset.ar.replace(/ر\.س/g,'SAR'):s.dataset.ar;});const totalLine=document.querySelector('.total-line');if(totalLine){const b=totalLine.querySelector('b');totalLine.innerHTML=(isEn?'Total (this product): ':'الإجمالي (للمنتج): ')+(b?b.outerHTML:'');}const panel=document.querySelector('.order-panel');if(panel){const h2=panel.querySelector('h2');if(h2)h2.textContent=d.checkout;[['customerName','name'],['customerPhone','phone'],['customerCity','city'],['customerAddress','address']].forEach(([id,key])=>{const x=document.getElementById(id);if(x)x.placeholder=d[key]});const pay=document.getElementById('payment');if(pay&&pay.options.length>1){pay.options[0].text=d.cod;pay.options[1].text=d.prepaid}const confirm=document.getElementById('confirm');if(confirm)confirm.textContent=d.confirm}}
function featureText(){const isEn=getLang()==='en';const data=isEn?[['Free shipping','Free delivery on orders over SAR 500'],['Secure payment','Secure and encrypted transactions'],['15-day returns','Easy returns within 15 days']]:[['شحن مجاني','توصيل مجاني للطلبات فوق 500 ر.س'],['دفع آمن','معاملات آمنة ومشفرة 100%'],['إرجاع 15 يوم','إرجاع سهل خلال 15 يوماً']];document.querySelectorAll('.feature').forEach((f,i)=>{const b=f.querySelector('b'),span=f.querySelector('span');if(b)b.textContent=data[i][0];if(span)span.textContent=data[i][1]})}
const legalEn={
'/legal/privacy-terms.html':'<h1>Privacy Policy &amp; Terms of Service</h1><p>This page explains the privacy policy and terms of use for the Syda store. Please read it before using the website or placing an order; using the store constitutes acceptance of these terms.</p><section id="privacy"><h2>Privacy Policy</h2><p>We respect your privacy and are committed to protecting your personal data. We use your data exclusively to process your orders and provide support, and we never sell or share your data with third parties for marketing or advertising purposes.</p><h3>Data we collect</h3><p>We collect only what is needed to complete and support your order: your name, phone number, region, city and delivery address.</p><h3>How we use your data</h3><ul><li>Processing, confirming and invoicing orders.</li><li>Arranging delivery through the appointed shipping provider.</li><li>Contacting you about your order or any product, return or exchange enquiries.</li></ul><h3>Payment security</h3><p>Payment details are handled by the approved payment provider, and we do not store your card numbers or payment data on our systems.</p><h3>Data sharing</h3><p>We only share your data with the parties strictly required to fulfil your order, the payment provider and the shipping company, and only to the extent necessary. We never rent or sell your data to any third party.</p><h3>Your rights</h3><p>You may at any time request access to, correction of, or deletion of your data through the official contact channels below, and we will process your request within a reasonable time.</p></section><section id="terms"><h2>Terms &amp; Conditions</h2><h3>Use of the store</h3><p>By using this store you agree to provide accurate and correct order information and to use the website lawfully, without misuse or attempts to harm its availability.</p><h3>Products and pricing</h3><p>Products and their descriptions are shown approximately. Product availability, pricing and delivery arrangements are subject to change, and some may be adjusted before an order is confirmed.</p><h3>Orders and confirmation</h3><p>Orders remain subject to confirmation until payment and stock are verified. An order is only considered confirmed once our team confirms it and you receive an order number.</p><h3>Payment methods</h3><p>You may pay cash on delivery, or prepay online to receive a 15% discount off the order value.</p><h3>Shipping, returns and exchanges</h3><p>The announced shipping fees apply (SAR 28, free for orders above SAR 500), and the delivery time depends on the region. Returns and exchanges are governed by the store shipping and returns policy.</p><h3>Intellectual property</h3><p>All website content, text, logos, images and trade names, is owned by or licensed to Syda, and may not be copied, reproduced or used commercially without prior permission.</p><h3>Disclaimer of liability</h3><p>We make reasonable efforts to display products and prices accurately, but slight differences in colours or details may occur between your screen and the actual product depending on your device settings, and images may not be to scale. The store is not liable for damage resulting from misuse of a product or failure to follow usage instructions, nor for delivery delays caused by circumstances beyond its control.</p><h3>Changes to these policies</h3><p>We may update these policies from time to time. Continuing to use the website after any update constitutes acceptance of the revised terms. We recommend reviewing this page periodically.</p></section><section id="contact"><h2>Contact us</h2><p>For any question about your data, your order or these policies, contact us through the official channels shown on the store or via the customer service email below.</p><div class="notice"><strong>Customer service email:</strong> <a href="mailto:info@taager.com">info@taager.com</a></div></section>',
'/legal/shipping-returns.html':'<h1>Shipping &amp; Returns &amp; Exchanges</h1><p>This page explains the shipping and delivery fees, and the returns and exchanges policy of the Syda store, together with the available payment methods.</p><section id="shipping"><h2>Shipping &amp; delivery</h2><h3>Shipping fees</h3><p>Shipping costs SAR 28 for eligible orders and is free for orders above SAR 500. Final fees are calculated based on your order total before confirmation.</p><h3>Delivery time</h3><p>Delivery time depends on the region and is confirmed once your order is confirmed.</p><h3>Order updates</h3><p>For delivery questions, use the official support channel and include your order number when available.</p><h3>Payment methods</h3><p>You may pay cash on delivery, or prepay online to receive a 15% discount off the order value.</p></section><section id="returns"><h2>Returns &amp; exchanges</h2><h3>Eligible products</h3><p>Eligible products may be returned or exchanged within 15 days of delivery if they are unused, in their original condition, and with their original packaging and accessories where applicable.</p><h3>Non-eligible products</h3><p>Returns are not accepted for personal-care, health or consumed products, or for products damaged by use that does not follow the instructions, unless the product arrived damaged or did not match the order.</p><h3>How to request a return</h3><p>Contact us with your order number and clear product photos when needed. Do not send an item before receiving the return instructions. Return shipping fees may apply depending on the reason for the return.</p><h3>Prepayment refunds</h3><p>For prepaid orders, the amount is refunded through the same payment method after the return is approved and verified, within a reasonable time.</p><p>This policy does not affect your statutory consumer protection rights.</p></section><section id="contact"><h2>Contact us</h2><p>For any question about shipping, delivery or returns, contact us through the official channels shown on the store or via the customer service email below.</p><div class="notice"><strong>Customer service email:</strong> <a href="mailto:info@taager.com">info@taager.com</a></div></section>',
'/legal/contact.html':'<h1>Contact us</h1><p>We are happy to help you with product, order, delivery and return enquiries.</p><div class="notice"><strong>Customer service email:</strong> <a href="mailto:info@taager.com">info@taager.com</a></div><form id="contactForm" class="contact-form" action="https://api.web3forms.com/submit" method="POST"><input type="hidden" name="access_key" value="59a5f464-a65e-4d63-a625-b0b85a9e6161"><input type="hidden" name="from" value="syda.pages.dev"><label>Full name<input type="text" name="name" required placeholder="Your name"></label><label>Your email<input type="email" name="email" required placeholder="you@example.com"></label><label>Phone (optional)<input type="tel" name="phone"></label><label>Subject<input type="text" name="subject" required placeholder="Order / Shipping / Return"></label><label>Message<textarea name="message" rows="5" required placeholder="Write your message..."></textarea></label><button type="submit" class="btn">Send message</button><p id="contactStatus" class="contact-status" role="status"></p></form><p>For faster support, please include the following:</p><h2>What we need from you</h2><ul><li>Your order number, if available.</li><li>The name and phone number used on the order.</li><li>A short description of the issue, with clear product photos when needed.</li></ul>'};
function legalText(){const legal=document.querySelector('.legal');if(!legal)return;if(!legal.dataset.arHtml)legal.dataset.arHtml=legal.innerHTML;const path=location.pathname.endsWith('.html')?location.pathname:`${location.pathname.replace(/\/$/,'')}.html`;if(getLang()==='en'&&legalEn[path])legal.innerHTML=legalEn[path];else legal.innerHTML=legal.dataset.arHtml}
function footerText(){const isEn=getLang()==='en',yr=new Date().getFullYear();document.querySelectorAll('.site-footer').forEach(f=>{f.innerHTML='<img class="logo" src="/assets/logo.png" alt="'+(isEn?'Syda':'صيدة')+'"><div class="footer-brand">'+(isEn?'Syda — Shop with confidence':'صيدة — تسوق بثقة')+'</div><nav class="footer-links"><a href="/legal/privacy-terms.html">'+(isEn?'Privacy Policy & Terms of Service':'سياسة الخصوصية والشروط')+'</a><a href="/legal/shipping-returns.html">'+(isEn?'Shipping & Returns & Exchanges':'الشحن والاستبدال والاسترجاع')+'</a></nav><a class="footer-contact" href="/legal/contact.html">'+(isEn?'Contact us':'تواصل معنا')+'</a><p class="footer-copy">© '+yr+' '+(isEn?'Syda — All rights reserved.':'صيدة — جميع الحقوق محفوظة.')+'</p>'})}
function applyLanguage(){const l=getLang();document.documentElement.lang=l;document.documentElement.dir=l==='en'?'ltr':'rtl';document.body.classList.toggle('lang-en',l==='en');document.body.classList.toggle('dark',localStorage.getItem('sayda-theme')==='dark');renderHeader();homeText();productText();featureText();legalText();footerText();window.dispatchEvent(new CustomEvent('languagechange',{detail:{lang:l}}))}
function setLanguage(l){localStorage.setItem('sayda-lang',l);applyLanguage()}
window.setLanguage=setLanguage;
document.addEventListener('submit',async function(ev){const f=ev.target;if(!f||f.id!=='contactForm')return;ev.preventDefault();const isEn=getLang()==='en';const showMsg=t=>{const box=document.getElementById('contactStatus');if(box){box.textContent=t;box.className='contact-status ok'}else alert(t)};const fd=new FormData(f);fd.set('from','syda.pages.dev');if(!fd.get('subject'))fd.set('subject',isEn?'New message from Syda':'رسالة جديدة من موقع صيدة');const btn=f.querySelector('button[type=submit]');if(btn)btn.disabled=true;try{const r=await fetch('https://api.web3forms.com/submit',{method:'POST',body:fd,headers:{'Accept':'application/json'}});const d=await r.json();if(d&&d.success){f.reset();showMsg(isEn?'Your message has been sent. We will reply soon.':'تم إرسال رسالتك بنجاح. سنرد عليك قريبًا.')}else{showMsg(isEn?'Sending failed. Please try again.':'عذرًا، فشل إرسال الرسالة. حاول مرة أخرى.')}}catch(e){showMsg(isEn?'Network error. Please try again.':'خطأ في الاتصال. حاول مرة أخرى.')}finally{if(btn)btn.disabled=false}});
