function saydaCityOptions(prov,en){const list=SA_CITIES[prov]||[];return`<option value="">${en?'City':'المدينة'}</option>`+list.map(c=>`<option value="${c[0]}">${en?c[1]:c[0]}</option>`).join('')}
function saydaBindCity(provEl,cityEl){if(!provEl||!cityEl)return;const fill=()=>{const keep=cityEl.value;cityEl.innerHTML=window.saydaCityOptions(provEl.value,cityEl.id.startsWith('cart')?isEnglish():(getLang()==='en'));if(keep&&Array.from(cityEl.options).some(o=>o.value===keep))cityEl.value=keep};provEl.addEventListener('change',fill);fill()}
function saydaCartTotals(){const cart=JSON.parse(localStorage.getItem('sayda-cart')||'[]');const sub=cart.reduce((n,p)=>n+(Number(p.price)||0)*(p.qty||1),0);const shipping=sub>=500?0:28;return{cart,sub,shipping,total:sub+shipping}}
function saydaBuildOrder(p){const c=saydaCartTotals();return{items:c.cart.map(x=>({productId:x.id,productName:x.name,nameEn:x.nameEn||x.name,quantity:x.qty||1,unitPrice:Number(x.price)||0,subtotal:(Number(x.price)||0)*(x.qty||1)})),subtotal:c.sub,codFee:0,total:c.total,deliveryInfo:{name:p.name,email:null,phone:p.phone,address:(p.city?p.city+' - ':'')+p.address,provinceId:p.province||null,zoneId:p.city||null,districtId:null,notes:null,saudiNationalAddress:null,countryIsoCode2:'SA'},apiKey:'',isPrePayment:!!p.isPrePayment,redirectionUrl:location.origin+'/thank-you?redirect=payment',metadata:{inlineCheckout:false,sessionKey:null,missedOrderId:null,eventId:(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random()),eventTime:Date.now(),userAgent:navigator.userAgent,consent:'granted'}}}
window.saydaSubmitOrder=async function(payload){try{const res=await fetch('/api/order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});let d={};try{d=await res.json()}catch(e){}return{ok:res.ok,data:d}}catch(e){return{ok:false,data:{message:String(e&&e.message||e)}}}}
window.saydaCartTotals=saydaCartTotals;window.saydaBuildOrder=saydaBuildOrder;window.SA_PROVINCES=SA_PROVINCES;window.SA_CITIES=SA_CITIES;window.saydaCityOptions=saydaCityOptions;window.saydaBindCity=saydaBindCity;window.saydaProvinceLabel=saydaProvinceLabel;
function wireProductOrder(){const panel=document.querySelector('.order-panel');const confirm=document.getElementById('confirm');if(!panel||!confirm)return;const addr=document.getElementById('customerAddress');let prov=document.getElementById('customerProvince');const cityIn=document.getElementById('customerCity');if(!prov){prov=document.createElement('select');prov.id='customerProvince';prov.innerHTML='<option value="">'+(getLang()==='en'?'Region':'المنطقة')+'</option>'+SA_PROVINCES.map(p=>`<option value="${p}">${saydaProvinceLabel(p,getLang()==='en')}</option>`).join('');(cityIn||addr).parentNode.insertBefore(prov,cityIn||addr)}if(cityIn&&cityIn.tagName!=='SELECT'){const sel=document.createElement('select');sel.id='customerCity';sel.innerHTML='<option value="">'+(getLang()==='en'?'City':'المدينة')+'</option>';cityIn.parentNode.replaceChild(sel,cityIn)}if(prov&&prov.tagName==='SELECT')window.saydaBindCity(prov,document.getElementById('customerCity'));confirm.onclick=async()=>{const g=(a,b)=>getLang()==='en'?a:b;const name=(document.getElementById('customerName').value||'').trim();const phone=(document.getElementById('customerPhone').value||'').trim();const city=(document.getElementById('customerCity').value||'').trim();const address=(document.getElementById('customerAddress').value||'').trim();const province=(document.getElementById('customerProvince').value||'').trim();const cart=saydaCartTotals().cart;if(!name||!phone||!province||!address){alert(g('Please complete name, phone, region and address.','يرجى إكمال الاسم والهاتف والمنطقة والعنوان.'));return}if(!cart.length){alert(g('Your cart is empty.','السلة فارغة.'));return}const isPre=(document.getElementById('payment')?.selectedIndex)===1;const payload=saydaBuildOrder({name,phone,province,city,address,isPrePayment:isPre});try{const r=await window.saydaSubmitOrder(payload);const d=r.data;if(r.ok&&d&&d.status==='success'&&d.orderId){localStorage.setItem('sayda-cart','[]');try{if(typeof window.saydaShowInvoice==='function'&&window.saydaShowInvoice({orderId:d.orderId,order:payload,isPre:isPre,paymentLink:d.paymentLink,date:new Date()})){return}}catch(e2){}alert(g('Order placed! Order number: '+d.orderId,'تم تأكيد الطلب! رقم الطلب: '+d.orderId));if(isPre&&d.paymentLink){location.href=d.paymentLink;return}location.reload()}else{alert((d&&d.message)||g('Could not place order. Please try again.','تعذر إرسال الطلب. حاول مرة أخرى.'))}}catch(e){alert(g('Network error placing order.','خطأ في الشبكة أثناء إرسال الطلب.'))}}}
// ===== Fix: product-page order modal i18n (overrides inline AR-only functions) =====
if(typeof renderOrder==='function')window.renderOrder=function(){const box=document.getElementById('orderItems');if(!box)return;const en=getLang()==='en',cu=en?'SAR':'ر.س',mr=v=>Number.isFinite(Number(v))?(Number(v).toFixed(2)+' '+cu):(en?'Price on request':'السعر عند الطلب'),ln=en?{sub:'Subtotal',ship:'Shipping',free:'Free',tot:'Total',empty:'Your cart is empty'}:{sub:'الإجمالي الفرعي',ship:'الشحن',free:'مجاني',tot:'الإجمالي',empty:'السلة فارغة'};if(!cart.length){box.innerHTML='<div class="notice">'+ln.empty+'</div>';return}const rows=cart.map((x,i)=>'<div class="notice"><b>'+(en?(x.nameEn||x.name):x.name)+'</b><br>'+mr(x.price)+' × '+(x.qty||1)+'<div class="qty"><button onclick="changeQty('+i+',-1)">−</button><span>'+(x.qty||1)+'</span><button onclick="changeQty('+i+',1)">+</button><button onclick="cart.splice('+i+',1);save();renderOrder()">'+(en?'Remove':'حذف')+'</button></div></div>').join('');const sub=cart.reduce((n,p)=>n+(Number(p.price)||0)*(p.qty||1),0),ship=sub>=500?0:28,tot=sub+ship;box.innerHTML=rows+'<div class="order-totals"><p>'+ln.sub+': <b>'+mr(sub)+'</b></p><p>'+ln.ship+': <b>'+(ship?mr(ship):ln.free)+'</b></p><p class="order-total">'+ln.tot+': <b>'+mr(tot)+'</b></p></div>'};
if(typeof addProduct==='function')window.addProduct=function(){const q=Math.max(1,Number(__tier)||1);const u=Number(product.price)||0;if(!u){alert(getLang()==='en'?'This product is priced on request. Please contact us.':'هذا المنتج سعره عند الطلب. تواصل معنا لمعرفة السعر.');return}const x={id:product.id,name:product.name,nameEn:product.nameEn||product.name,price:u,qty:q};const old=cart.find(y=>y.id===x.id);if(old)old.qty=(old.qty||1)+q;else cart.push(x);save();openOrder()};
const _ab=document.getElementById('a');if(_ab&&_ab.onclick&&typeof window.addProduct==='function')_ab.onclick=window.addProduct;
if(typeof __wireRelated==='function'){window.__wireRelated=function(){const wrap=document.getElementById('relatedGrid');if(!wrap)return;wrap.onclick=e=>{const b=e.target.closest('.add');if(!b)return;const r=(window.__related||[]).find(x=>x.id===b.dataset.id);if(!r)return;const old=cart.find(y=>y.id===r.id);if(old)old.qty=(old.qty||1)+1;else cart.push({id:r.id,name:r.name,nameEn:r.nameEn||r.name,price:r.price,qty:1});save();openOrder()}};__wireRelated()}
window.addEventListener('languagechange',()=>{const om=document.getElementById('orderModal');if(om&&om.style.display==='flex'&&typeof renderOrder==='function')renderOrder()});
// ===== Fix: product breadcrumb category link → category page (not home?cat=) =====
if(typeof __renderCrumbs==='function'){window.__renderCrumbs=function(){const c=document.querySelector('.crumbs');if(!c)return;const en=__isEn(),home=en?'Home':'الرئيسية',det=en?'Product details':'تفاصيل المنتج',cat=encodeURIComponent(c.dataset.cat||''),lab=en?(c.dataset.caten||c.dataset.catlabel):c.dataset.catlabel;c.innerHTML='<a href="/">'+home+'</a> ← '+(cat?'<a href="/categories/'+cat+'.html">'+lab+'</a> ← ':'')+'<span>'+det+'</span>'};__renderCrumbs()}
document.addEventListener('DOMContentLoaded',()=>{applyLanguage();wireProductOrder()});
