      ov.innerHTML='<div id="saydaInvCard"><div id="saydaInvBar"><h3></h3><button class="sayda-dl" data-dl></button>'+payBtn+'<button class="sayda-pp" data-pp></button><button class="sayda-cl" data-cl></button></div><div id="saydaInvScroll"></div></div>';
      document.body.appendChild(ov);__renderInv(__siteLang());
